import React, { useEffect, useState, useCallback } from 'react';
import { Card, Table, Tag, Typography, Space, Statistic, Row, Col } from 'antd';
import { DesktopOutlined, CloudServerOutlined, ThunderboltOutlined } from '@ant-design/icons';

const STATUS_COLOR = {
  online: 'green',
  busy: 'gold',
  offline: 'default',
  pending: 'blue',
};

export default function RpaControlRoomPage() {
  const [agents, setAgents] = useState([]);
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    const res = await window.metadata.dataApi.list('sys_rpa_agent', { page: 1, pageSize: 200, sort: 'name' });
    setAgents(res.data || []);
    setLoading(false);
  }, []);

  useEffect(() => { load(); }, [load]);

  // Agents connect over the /rpa-agents namespace (a separate, agent-token
  // authenticated Socket.io namespace from the one this page's own
  // getSocket() call returns); the gateway relays status changes onto this
  // page's namespace as "rpa:agent:status" so the grid updates live.
  useEffect(() => {
    const socket = window.metadata.getSocket();
    if (!socket) return;
    const onStatus = (evt) => {
      setAgents((prev) => prev.map((a) => (a.id === evt.id ? { ...a, status: evt.status, last_heartbeat_at: evt.last_heartbeat_at } : a)));
    };
    socket.on('rpa:agent:status', onStatus);
    return () => socket.off('rpa:agent:status', onStatus);
  }, []);

  const online = agents.filter((a) => a.status === 'online' || a.status === 'busy').length;

  const columns = [
    { title: 'Name', dataIndex: 'name', key: 'name' },
    { title: 'Pool', dataIndex: 'pool_id', key: 'pool_id' },
    { title: 'Hostname', dataIndex: 'hostname', key: 'hostname' },
    { title: 'Mode', dataIndex: 'mode', key: 'mode' },
    {
      title: 'Status',
      dataIndex: 'status',
      key: 'status',
      render: (status) => <Tag color={STATUS_COLOR[status] || 'default'}>{status}</Tag>,
    },
    {
      title: 'Last Heartbeat',
      dataIndex: 'last_heartbeat_at',
      key: 'last_heartbeat_at',
      render: (v) => (v ? new Date(v).toLocaleString() : '—'),
    },
  ];

  return (
    <Space direction="vertical" style={{ width: '100%' }} size="large">
      <Card>
        <Row gutter={32}>
          <Col><Statistic title="Registered Agents" value={agents.length} prefix={<DesktopOutlined />} /></Col>
          <Col><Statistic title="Online / Busy" value={online} prefix={<CloudServerOutlined />} valueStyle={{ color: online > 0 ? '#3f8600' : undefined }} /></Col>
          <Col><Statistic title="Offline" value={agents.length - online} prefix={<ThunderboltOutlined />} /></Col>
        </Row>
      </Card>
      <Card title="Agents">
        <Table rowKey="id" loading={loading} columns={columns} dataSource={agents} pagination={false} />
        <Typography.Paragraph type="secondary" style={{ marginTop: 16 }}>
          To enroll a new agent: create a row here first (Name + Pool), then on that machine run{' '}
          <code>node src/cli.js enroll --server &lt;url&gt; --agent-id &lt;id&gt;</code> followed by{' '}
          <code>node src/cli.js start</code> from the <code>/agent</code> folder.
        </Typography.Paragraph>
      </Card>
    </Space>
  );
}
